        {capability.kind==='managed'?<><p className="muted">{releases.at(-1)?.manifest.description}</p><ManagedCapabilityFacts value={capability} releases={releases}/><details open={!releases.length}><summary>{releases.length?'Install another version':'Install a version'}</summary><p className="muted">Use the full Git commit of the tool version to build.</p><label>Git commit<input value={installCommit} onChange={event=>setInstallCommit(event.target.value)} placeholder="40-character commit"/></label><button className="primary" disabled={busy||!available||!/^([a-f0-9]{40})$/.test(installCommit.trim())} onClick={()=>void run(async()=>{await command({kind:'release.install',packageId:capability.id,commit:installCommit.trim()});setInstallCommit('');})}>Install version</button></details>{releases.map(value=><article className="environment-card" key={value.id}><strong>{value.manifest.name}</strong><p className="muted">Commit <code>{value.commit}</code></p><p className="muted">Release {value.id} · installed {new Date(value.createdAt).toLocaleString()}</p><details><summary>Release provenance</summary><dl className="environment-facts"><dt>Commit</dt><dd>{value.commit}</dd><dt>Artifact</dt><dd>{value.artifactDigest}</dd><dt>Runtime image</dt><dd>{value.image}</dd></dl></details></article>)}</>:<>{capabilityInspectionError&&<p role="status" className="environment-error">Capability observation unavailable: {capabilityInspectionError}</p>}{capabilityFacts?<CapabilityFacts value={capabilityFacts.component} installation={capabilityFacts.installation} platform={capabilityFacts.installation??(capability.kind==='stdio'?capability.identity:undefined)} connectionEvidence={capabilityFacts.environments.length?<>{capabilityFacts.environments.map(value=><article className="capability-environment" key={`${value.environmentId}:${value.componentId}`}><p><button onClick={()=>choose(value.environmentId)}>{value.name}</button> · {value.evidence.connection==='untested'?'Connection untested':value.evidence.connection==='connected'?`Connected · ${value.evidence.tools.length} ${value.evidence.tools.length===1?'tool':'tools'}`:'Connection failed'}</p>{value.evidence.checks.filter(check=>check.status==='failed').map(check=><p className="environment-error" key={check.name}>{check.name}: failed</p>)}<details><summary>Validation details</summary><EvidenceFacts value={value.evidence}/><p>Environment version: {value.revisionId}</p><p>Component: {value.componentId}</p></details></article>)}</>:undefined} authentication={<CapabilityAuthentication key={`${capability.id}:${capability.revisionId}`} subject={{kind:'registered',value:capability}} active={active} pollMs={pollMs} command={command} onPrepared={acceptPrepared} onAuthenticated={acceptCapability}/>}/>:<p className="muted">Loading capability properties…</p>}</>}
        {!!inventory?.preparations.some(plan=>plan.result.environmentId!==null&&plan.result.components.some(value=>value.capabilityId===capability.id||releases.some(release=>release.id===value.capabilityId)))&&<section><h2>Environment preparations</h2><p className="muted">Continue a retained preparation explicitly to compose its selected capabilities into an environment.</p>{inventory.preparations.filter(plan=>plan.result.environmentId!==null&&plan.result.components.some(value=>value.capabilityId===capability.id||releases.some(release=>release.id===value.capabilityId))).map(plan=><button key={plan.result.operationId} onClick={()=>{setRetainedInput(preparationDraft(plan));setReviewInput(null);setPreparation(plan.result);preparationTarget.current=plan.result.operationId;setPreparing(true);}}>Open {plan.name}</button>)}</section>}
