      {preview&&<div aria-live="polite">{preview.errors.map((value,index)=><p className="environment-error" key={`${value.name}-${index}`}>{value.name}: {value.message} ({value.code})</p>)}{Object.keys(preview.resolutions).length>0&&<section><h3>Confirm installed executables</h3>{Object.entries(preview.resolutions).map(([entry,path])=><p key={entry}>{entry}: <code>{path}</code></p>)}<button disabled={busy} onClick={()=>void run(()=>previewImport({...resolutions,...preview.resolutions}))}>Confirm executable paths and preview</button></section>}{preview.entries.map(value=><article className="environment-card" key={value.name}><strong>{value.name}</strong><p>{definitionLabel(value.definition)}</p><p className="muted">{value.definition.kind==='http'?value.definition.url:value.definition.command}</p>{value.definition.kind==='stdio'&&<p>Each worker launches its own process with your user account's authority, in its own workspace. Package installations are shared; runtime scratch is separate. Polariton supervises foreground processes; it does not provide a filesystem sandbox.</p>}{value.definition.kind==='stdio'&&value.definition.package&&<p>Apply prepares {packageLabel(value.definition.package)} once for this revision. Starting or resuming a worker never installs it.</p>}<p className="muted">{Object.keys(value.definition.credentials).length?'Private credential references required':'No credential references'} · {value.definition.requirements.files.length} prerequisite files</p></article>)}{editing&&preview.entries.length!==1&&<p className="environment-error">An update must contain exactly one capability.</p>}</div>}
